import math

def f(n):
    """Returns the largest odd divisor of n."""
    if n <= 0:
        raise ValueError("n must be a positive integer")
    while n % 2 == 0:
        n //= 2
    return n

def check_condition(v, u):
    """Checks if the condition holds for given v and u."""
    # The sequence of differences runs from k=0 up to v-1
    for k in range(v):
        diff = f(u + v + k) - f(u + k)
        if diff % 4 != 0:
            return False
    return True

# Target search parameters
odd_v_range = range(7, 20, 2)  # v in {7, 9, 11, 13, 15, 17, 19}
U_max = 10000

successful_pairs = {}

print(f"Starting computational search for odd v in [7, 19] and u up to {U_max}...")

for v in odd_v_range:
    successful_pairs[v] = []
    count = 0
    for u in range(1, U_max + 1):
        if check_condition(v, u):
            successful_pairs[v].append(u)
            count += 1

    print(f"Completed search for v={v}. Found {count} successful pairs.")

